1	/**
2	 * @module features/tv-dashboard/model/tvMath
3	 *
4	 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
5	 * delta semanal, classificação RAG, formatação compacta de moeda,
6	 * staleness e agregações determinísticas usadas pelo hook de dados.
7	 *
8	 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
9	 */
10	
11	import type {
12	  TvBusinessHours,
13	  TvException,
14	  TvExceptionsResult,
15	  TvFreshnessLevel,
16	  TvRagStatus,
17	  TvStockAlertItem,
18	} from './types';
19	
20	// ─────────────────────────────────────────────────────────────────────────────
21	// Constantes de negócio
22	// ─────────────────────────────────────────────────────────────────────────────
23	
24	/**
25	 * Janela de funcionamento das lojas usada no pró-rata da meta (hora local).
26	 * AJUSTÁVEL: se o horário comercial mudar, basta alterar aqui — todos os
27	 * cálculos de pró-rata e de "sem movimentação" derivam desta constante.
28	 */
29	export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 9, end: 21 };
30	
31	/** Horas sem movimentação (dentro da janela) que tornam a loja âmbar. */
32	export const NO_MOVEMENT_THRESHOLD_HOURS = 3;
33	
34	/** % do esperado pró-rata abaixo do qual a venda live torna a loja vermelha. */
35	export const LIVE_SALES_RED_THRESHOLD_PCT = 50;
36	
37	/** Máximo de linhas exibidas na faixa de exceções. */
38	export const TV_EXCEPTIONS_LIMIT = 7;
39	
40	// ─────────────────────────────────────────────────────────────────────────────
41	// Datas (helpers locais, sem dependência de timezone UTC)
42	// ─────────────────────────────────────────────────────────────────────────────
43	
44	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
45	export function toIsoDateLocal(d: Date): string {
46	  const y = d.getFullYear();
47	  const m = String(d.getMonth() + 1).padStart(2, '0');
48	  const day = String(d.getDate()).padStart(2, '0');
49	  return `${y}-${m}-${day}`;
50	}
51	
52	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
53	export function parseIsoDateLocal(iso: string): Date {
54	  const [y, m, d] = iso.split('-').map(Number);
55	  return new Date(y, (m ?? 1) - 1, d ?? 1);
56	}
57	
58	/** Soma `days` dias a uma data, retornando nova instância. */
59	export function addDays(d: Date, days: number): Date {
60	  const out = new Date(d);
61	  out.setDate(out.getDate() + days);
62	  return out;
63	}
64	
65	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
66	export function formatLaggedDateLabel(isoDate: string): string {
67	  const d = parseIsoDateLocal(isoDate);
68	  const dd = String(d.getDate()).padStart(2, '0');
69	  const mm = String(d.getMonth() + 1).padStart(2, '0');
70	  return `até ${dd}/${mm}`;
71	}
72	
73	// ─────────────────────────────────────────────────────────────────────────────
74	// Pró-rata da meta
75	// ─────────────────────────────────────────────────────────────────────────────
76	
77	/**
78	 * Fração linear do dia comercial já decorrida em `now`.
79	 *
80	 * - Antes da abertura → 0 (não há venda esperada ainda).
81	 * - Depois do fechamento → 1 (meta integral esperada).
82	 * - Dentro da janela → interpolação linear simples (pró-rata).
83	 */
84	export function businessDayFraction(
85	  now: Date,
86	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
87	): number {
88	  const { start, end } = hours;
89	  if (end <= start) {
90	    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
91	    return now.getHours() >= end ? 1 : 0;
92	  }
93	  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
94	  if (h <= start) return 0;
95	  if (h >= end) return 1;
96	  return (h - start) / (end - start);
97	}
98	
99	/**
100	 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
101	 *
102	 * Retorna null quando não dá para calcular com honestidade:
103	 * - meta ausente/zerada (sem referência), ou
104	 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
105	 */
106	export function pctOfProRataTarget(
107	  sold: number,
108	  dailyTarget: number | null | undefined,
109	  now: Date,
110	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
111	): number | null {
112	  if (dailyTarget == null || dailyTarget <= 0) return null;
113	  const fraction = businessDayFraction(now, hours);
114	  if (fraction <= 0) return null;
115	  return (sold / (dailyTarget * fraction)) * 100;
116	}
117	
118	/**
119	 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
120	 * cujo dia de referência já encerrou.
121	 */
122	export function pctOfFullDayTarget(
123	  sold: number,
124	  dailyTarget: number | null | undefined,
125	): number | null {
126	  if (dailyTarget == null || dailyTarget <= 0) return null;
127	  return (sold / dailyTarget) * 100;
128	}
129	
130	// ─────────────────────────────────────────────────────────────────────────────
131	// Delta semanal
132	// ─────────────────────────────────────────────────────────────────────────────
133	
134	/**
135	 * Delta % vs MESMO DIA da semana anterior (nunca "ontem" — spec).
136	 * Retorna null quando a base de comparação é ausente ou não positiva.
137	 */
138	export function weekOverWeekDelta(
139	  current: number,
140	  lastWeek: number | null | undefined,
141	): number | null {
142	  if (lastWeek == null || lastWeek <= 0) return null;
143	  return ((current - lastWeek) / lastWeek) * 100;
144	}
145	
146	// ─────────────────────────────────────────────────────────────────────────────
147	// RAG da loja
148	// ─────────────────────────────────────────────────────────────────────────────
149	
150	/** Entrada da classificação RAG de uma unidade. */
151	export interface StoreRagInput {
152	  /** Itens zerados em alerta (quantidade ≤ 0 com mínimo definido). */
153	  stockOutCount: number;
154	  /** Itens abaixo do mínimo (quantidade entre 0 exclusivo e o mínimo). */
155	  stockLowCount: number;
156	  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
157	  pctMetaProRata: number | null;
158	  /** true quando a unidade tem venda ao vivo (canal Degust). */
159	  isLiveChannel: boolean;
160	  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
161	  lastMovementAt: Date | string | null;
162	  /** Instante da avaliação. */
163	  now: Date;
164	  hours?: TvBusinessHours;
165	}
166	
167	/**
168	 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
169	 *
170	 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
171	 *   não faz sentido alertar madrugada sem bipagem.
172	 * - A referência é clampada ao início da janela de hoje: se a última
173	 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
174	 */
175	export function hoursWithoutMovementInWindow(
176	  lastMovementAt: Date | string | null,
177	  now: Date,
178	  hours: TvBusinessHours = TV_BUSINESS_HOURS,
179	): number | null {
180	  const fraction = businessDayFraction(now, hours);
181	  if (fraction <= 0 || fraction >= 1) return null;
182	  const windowStart = new Date(now);
183	  windowStart.setHours(hours.start, 0, 0, 0);
184	  const last = lastMovementAt
185	    ? new Date(lastMovementAt).getTime()
186	    : Number.NEGATIVE_INFINITY;
187	  const ref = Math.max(last, windowStart.getTime());
188	  return (now.getTime() - ref) / 3_600_000;
189	}
190	
191	/**
192	 * Classificação RAG de uma unidade (management-by-exception).
193	 *
194	 * Regras (ordem de precedência):
195	 * - VERMELHO: existe item zerado em alerta (`stockOutCount > 0`) OU a venda
196	 *   live está abaixo de {@link LIVE_SALES_RED_THRESHOLD_PCT}% do esperado
197	 *   pró-rata (somente canal live e quando há meta → pct != null).
198	 * - ÂMBAR: existem itens abaixo do mínimo (`stockLowCount > 0`) OU a unidade
199	 *   está sem movimentação há mais de {@link NO_MOVEMENT_THRESHOLD_HOURS}h
200	 *   dentro da janela de funcionamento.
201	 * - OK: nenhum desvio — tela calma, sem cor.
202	 */
203	export function classifyStoreRag(input: StoreRagInput): {
204	  status: TvRagStatus;
205	  reasons: string[];
206	} {
207	  const hours = input.hours ?? TV_BUSINESS_HOURS;
208	  const reasons: string[] = [];
209	
210	  // ── Vermelho ──
211	  if (input.stockOutCount > 0) {
212	    reasons.push(
213	      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
214	    );
215	  }
216	  if (
217	    input.isLiveChannel &&
218	    input.pctMetaProRata !== null &&
219	    input.pctMetaProRata < LIVE_SALES_RED_THRESHOLD_PCT
220	  ) {
221	    reasons.push(
222	      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
223	    );
224	  }
225	  if (reasons.length > 0) return { status: 'red', reasons };
226	
227	  // ── Âmbar ──
228	  if (input.stockLowCount > 0) {
229	    reasons.push(
230	      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
231	    );
232	  }
233	  const gapHours = hoursWithoutMovementInWindow(
234	    input.lastMovementAt,
235	    input.now,
236	    hours,
237	  );
238	  if (gapHours !== null && gapHours > NO_MOVEMENT_THRESHOLD_HOURS) {
239	    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
240	  }
241	  if (reasons.length > 0) return { status: 'amber', reasons };
242	
243	  return { status: 'ok', reasons: [] };
244	}
245	
246	// ─────────────────────────────────────────────────────────────────────────────
247	// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
248	// ─────────────────────────────────────────────────────────────────────────────
249	
250	function trimOneDecimal(v: number): string {
251	  const rounded = Math.round(v * 10) / 10;
252	  return rounded.toLocaleString('pt-BR', {
253	    minimumFractionDigits: 0,
254	    maximumFractionDigits: 1,
255	  });
256	}
257	
258	/**
259	 * Formata um valor em BRL compacto para leitura a 3-5 metros:
260	 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
261	 * Valores negativos preservam o sinal ("-R$ 1,2k").
262	 */
263	export function formatCompactBRL(value: number): string {
264	  const sign = value < 0 ? '-' : '';
265	  const abs = Math.abs(value);
266	  // Bump pra M quando o arredondamento em k chegaria a 1000k
267	  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
268	    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
269	  }
270	  if (abs >= 1_000) {
271	    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
272	  }
273	  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
274	}
275	
276	// ─────────────────────────────────────────────────────────────────────────────
277	// Staleness
278	// ─────────────────────────────────────────────────────────────────────────────
279	
280	/**
281	 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
282	 * - `fresh`: idade abaixo de 2× o intervalo esperado (tolera um ciclo perdido).
283	 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
284	 * - `very-stale`: idade a partir de 6×, timestamp inválido ou ausente.
285	 */
286	export function classifyStaleness(
287	  lastUpdatedAt: Date | string | number | null | undefined,
288	  expectedIntervalMs: number,
289	  now: Date,
290	): TvFreshnessLevel {
291	  if (lastUpdatedAt == null) return 'very-stale';
292	  const ts = new Date(lastUpdatedAt).getTime();
293	  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
294	  const age = now.getTime() - ts;
295	  if (age < 2 * expectedIntervalMs) return 'fresh';
296	  if (age < 6 * expectedIntervalMs) return 'stale';
297	  return 'very-stale';
298	}
299	
300	// ─────────────────────────────────────────────────────────────────────────────
301	// Exceções — ordenação e corte
302	// ─────────────────────────────────────────────────────────────────────────────
303	
304	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
305	const KIND_ORDER: Record<string, number> = {
306	  'stock-out': 0,
307	  'no-movement': 1,
308	  'stock-low': 2,
309	  'stale-data': 3,
310	};
311	
312	/**
313	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
314	 * (falta total, sem movimentação, abaixo do mínimo, dado stale — nesta ordem)
315	 * e por mensagem (estável), limitando a `limit` linhas com contagem do excedente.
316	 */
317	export function sortAndLimitExceptions(
318	  exceptions: TvException[],
319	  limit: number = TV_EXCEPTIONS_LIMIT,
320	): TvExceptionsResult {
321	  const sorted = [...exceptions].sort((a, b) => {
322	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
323	    if (sev !== 0) return sev;
324	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
325	    if (kind !== 0) return kind;
326	    return a.message.localeCompare(b.message, 'pt-BR');
327	  });
328	  return {
329	    items: sorted.slice(0, limit),
330	    overflowCount: Math.max(0, sorted.length - limit),
331	    totalCount: sorted.length,
332	  };
333	}
334	
335	// ─────────────────────────────────────────────────────────────────────────────
336	// Agregações determinísticas usadas pelo hook (puras, testáveis)
337	// ─────────────────────────────────────────────────────────────────────────────
338	
339	/** Linha mínima de `movimentacoes` necessária à agregação. */
340	export interface MovementRow {
341	  loja_id: number | null;
342	  tipo_movimentacao: string;
343	  data_movimentacao: string | null;
344	}
345	
346	/** Resultado por loja da agregação de movimentações do dia. */
347	export interface MovementAggregate {
348	  entradas: number;
349	  saidas: number;
350	  ultimaBipagem: string | null;
351	}
352	
353	/**
354	 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
355	 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
356	 * são ignoradas.
357	 */
358	export function aggregateMovements(
359	  rows: MovementRow[],
360	): Map<number, MovementAggregate> {
361	  const out = new Map<number, MovementAggregate>();
362	  for (const row of rows) {
363	    if (row.loja_id == null) continue;
364	    let agg = out.get(row.loja_id);
365	    if (!agg) {
366	      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
367	      out.set(row.loja_id, agg);
368	    }
369	    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
370	    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
371	    if (
372	      row.data_movimentacao &&
373	      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
374	    ) {
375	      agg.ultimaBipagem = row.data_movimentacao;
376	    }
377	  }
378	  return out;
379	}
380	
381	/** Linha mínima de `estoque` (com nome do produto ativo já joinado). */
382	export interface StockRow {
383	  loja_id: number | null;
384	  quantidade_atual: number | null;
385	  quantidade_minima: number | null;
386	  produtoNome: string;
387	}
388	
389	/** Detalhe de alertas de estoque por loja. */
390	export interface StockDetail {
391	  zerados: number;
392	  abaixoMinimo: number;
393	  itens: TvStockAlertItem[];
394	}
395	
396	/**
397	 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
398	 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
399	 * query). Regras (critério existente do projeto, sem schema novo):
400	 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
401	 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
402	 */
403	export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
404	  const out = new Map<number, StockDetail>();
405	  for (const row of rows) {
406	    if (row.loja_id == null) continue;
407	    const min = row.quantidade_minima ?? 0;
408	    if (min <= 0) continue; // sem mínimo definido → sem alerta
409	    const qty = row.quantidade_atual ?? 0;
410	    if (qty >= min) continue; // dentro do normal
411	    let detail = out.get(row.loja_id);
412	    if (!detail) {
413	      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
414	      out.set(row.loja_id, detail);
415	    }
416	    const zerado = qty <= 0;
417	    if (zerado) detail.zerados += 1;
418	    else detail.abaixoMinimo += 1;
419	    detail.itens.push({
420	      produtoNome: row.produtoNome,
421	      quantidade: qty,
422	      quantidadeMinima: min,
423	      zerado,
424	    });
425	  }
426	  return out;
427	}
428	
429	/**
430	 * Constrói as exceções de estoque (item × loja) a partir do detalhe por loja.
431	 * Itens zerados viram exceção vermelha; abaixo do mínimo, âmbar.
432	 */
433	export function buildStockExceptions(
434	  detailByLoja: Map<number, StockDetail>,
435	  lojaNomeById: Map<number, string>,
436	): TvException[] {
437	  const out: TvException[] = [];
438	  for (const [lojaId, detail] of detailByLoja) {
439	    const lojaNome = lojaNomeById.get(lojaId) ?? `Loja ${lojaId}`;
440	    for (const item of detail.itens) {
441	      out.push({
442	        id: `${item.zerado ? 'stock-out' : 'stock-low'}:${lojaId}:${item.produtoNome}`,
443	        kind: item.zerado ? 'stock-out' : 'stock-low',
444	        severity: item.zerado ? 'red' : 'amber',
445	        lojaId,
446	        lojaNome,
447	        message: item.zerado
448	          ? `${item.produtoNome} zerado — ${lojaNome}`
449	          : `${item.produtoNome} abaixo do mínimo (${item.quantidade}/${item.quantidadeMinima}) — ${lojaNome}`,
450	        produtoNome: item.produtoNome,
451	        quantidade: item.quantidade,
452	        quantidadeMinima: item.quantidadeMinima,
453	      });
454	    }
455	  }
456	  return out;
457	}
458	
459	/** Linha de venda live normalizada (resposta da edge `degust-pos-financial`). */
460	export interface FlashRow {
461	  loja_id: number;
462	  nome_loja: string;
463	  total_vendas: number;
464	  total_cupons: number;
465	  ticket_medio: number;
466	  caixa_aberto: boolean;
467	  ultima_atualizacao: string | null;
468	}
469	
470	/**
471	 * Corrige o `loja_id` das linhas de flash-vendas.
472	 *
473	 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
474	 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
475	 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
476	 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
477	 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
478	 *
479	 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
480	 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
481	 * - Caso contrário → descarta (não corromper outra loja).
482	 */
483	export function remapFlashLojaIds(
484	  rows: FlashRow[],
485	  degustCodeToLoja: ReadonlyMap<number, number>,
486	  knownDegustLojaIds: ReadonlySet<number>,
487	): FlashRow[] {
488	  const out: FlashRow[] = [];
489	  for (const row of rows) {
490	    if (knownDegustLojaIds.has(row.loja_id)) {
491	      out.push(row);
492	      continue;
493	    }
494	    const mapped = degustCodeToLoja.get(row.loja_id);
495	    if (mapped != null) {
496	      out.push({ ...row, loja_id: mapped });
497	    }
498	    // não mapeável → descartado de propósito (ver TSDoc)
499	  }
500	  return out;
501	}
502	
503	/** Linha mínima de `degust_vendas_diarias` para o top produtos. */
504	export interface DailyProductRow {
505	  degust_nome: string;
506	  quantidade: number | null;
507	  valor_total: number | null;
508	}
509	
510	/** Produto agregado do dia (rede). */
511	export interface TvTopProduct {
512	  nome: string;
513	  quantidade: number;
514	  valor: number;
515	}
516	
517	/**
518	 * Top N produtos do dia da rede, agregando `degust_vendas_diarias` por nome.
519	 * Ranking por quantidade vendida (desempate por valor).
520	 */
521	export function topProductsFromDaily(
522	  rows: DailyProductRow[],
523	  n = 5,
524	): TvTopProduct[] {
525	  const byName = new Map<string, TvTopProduct>();
526	  for (const row of rows) {
527	    let agg = byName.get(row.degust_nome);
528	    if (!agg) {
529	      agg = { nome: row.degust_nome, quantidade: 0, valor: 0 };
530	      byName.set(row.degust_nome, agg);
531	    }
532	    agg.quantidade += row.quantidade ?? 0;
533	    agg.valor += row.valor_total ?? 0;
534	  }
535	  return [...byName.values()]
536	    .sort((a, b) => b.quantidade - a.quantidade || b.valor - a.valor)
537	    .slice(0, n);
538	}
