85	// ─────────────────────────────────────────────────────────────────────────────
86	// Contexto: lojas + canais (derivados em runtime, sem hardcode de loja_id)
87	// ─────────────────────────────────────────────────────────────────────────────
88	
89	interface TvLoja {
90	  id: number;
91	  nome: string;
92	  tipo: string | null;
93	}
94	
95	interface TvContext {
96	  lojas: TvLoja[];
97	  /** Lojas com venda live (existem em `degust_stores`). */
98	  degustLojaIds: Set<number>;
99	  /** Mapa código Degust → loja_id (corrige pass-through da edge function). */
100	  degustCodeToLoja: Map<number, number>;
101	  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
102	  linxLojaIds: number[];
103	  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
104	  factoryLojaId: number | null;
105	}
106	
107	function isFactoryTipo(tipo: string | null): boolean {
108	  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
109	  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
110	}
111	
112	async function fetchTvContext(): Promise<TvContext> {
113	  const [lojasRes, degustRes] = await Promise.all([
114	    supabase
115	      .from('lojas')
116	      .select('id, nome, tipo')
117	      .eq('ativo', true)
118	      .order('id'),
119	    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
120	  ]);
121	  if (lojasRes.error) throw lojasRes.error;
122	  if (degustRes.error) throw degustRes.error;
123	
124	  const lojas: TvLoja[] = lojasRes.data ?? [];
125	  const degustLojaIds = new Set<number>();
126	  const degustCodeToLoja = new Map<number, number>();
127	  for (const row of degustRes.data ?? []) {
128	    degustLojaIds.add(row.loja_id);
129	    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
130	  }
131	
132	  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
133	  const linxLojaIds = lojas
134	    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
135	    .map((l) => l.id);
136	
137	  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
138	}
