1	/**
2	 * @module features/tv-dashboard/ui/TvStoreCard
3	 *
4	 * Card de loja do Painel TV (602×280 — design.md §4): vendas do dia (ou
5	 * defasadas com selo honesto), barra de % meta, mini-stats e borda RAG
6	 * com redundância não-cromática (glow + chip de estado).
7	 */
8	
9	import { ArrowDownRight, ArrowUpRight } from 'lucide-react';
10	import type { TvFreshnessLevel, TvStoreData } from '../model/types';
11	import { formatCompactBRL, parseIsoDateLocal } from '../model/tvMath';
12	import {
13	  TvDeltaChip,
14	  TvMetaBar,
15	  TvSourceChip,
16	  TvStateChip,
17	  TvStockBadge,
18	} from './TvChips';
19	import {
20	  WEEKDAY_ABBR,
21	  expectedPctNow,
22	  formatInt,
23	  formatTicketBRL,
24	  formatTimeHHMM,
25	  formatWeekdayDayMonth,
26	  metaBarColorFromRatio,
27	} from './tvFormat';
28	import { useCountUp } from './useCountUp';
29	
30	interface TvStoreCardProps {
31	  store: TvStoreData;
32	  /** Freshness consolidado da fonte de vendas live (chip "ao vivo"/"atrasado"). */
33	  liveLevel: TvFreshnessLevel;
34	  now: Date;
35	}
36	
37	/** Borda + glow por estado RAG (design.md §4 — sinal lível a 5m). */
38	const RAG_FRAME: Record<TvStoreData['rag'], { cls: string; shadow?: string }> = {
39	  ok: { cls: 'border border-tv-border' },
40	  amber: {
41	    cls: 'border-2 border-tv-amber',
42	    shadow: '0 0 0 1px #F5A623, 0 0 28px -8px rgba(245,166,35,0.45)',
43	  },
44	  red: {
45	    cls: 'border-2 border-tv-red',
46	    shadow: '0 0 0 1px #E5484D, 0 0 32px -8px rgba(229,72,77,0.55)',
47	  },
48	};
49	
50	/** Card de loja: cobre canal Degust live e Linx defasado. */
51	export function TvStoreCard({ store, liveLevel, now }: TvStoreCardProps) {
52	  const { vendas, metaDia, channel } = store;
53	  const isLive = channel === 'degust-live';
54	  const valorAnim = useCountUp(vendas?.valor ?? 0);
55	  const cuponsAnim = Math.round(useCountUp(vendas?.cupons ?? 0));
56	  const frame = RAG_FRAME[store.rag];
57	
58	  // Barra: preenchimento = % do dia COMPLETO; tick pró-rata só no canal live
59	  const fullDayPct =
60	    vendas != null && metaDia != null && metaDia > 0
61	      ? (vendas.valor / metaDia) * 100
62	      : null;
63	  const expected = isLive ? expectedPctNow(now) : null;
64	  const barColor = isLive
65	    ? metaBarColorFromRatio(store.pctMeta != null ? store.pctMeta / 100 : null, now)
66	    : 'sage';
67	
68	  const bipTime = formatTimeHHMM(store.movimentacao.ultimaBipagem);
69	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
70	
71	  // Caption sob as vendas (design.md §4 item 4)
72	  let caption: string;
73	  if (vendas == null) {
74	    caption = 'sem dado de venda disponível';
75	  } else if (isLive) {
76	    const upd = formatTimeHHMM(vendas.atualizadoEm);
77	    caption = `hoje${upd ? ` · atualizado ${upd}` : ''}${bipTime ? ` · bip ${bipTime}` : ''}`;
78	  } else {
79	    caption = `${refDate ? formatWeekdayDayMonth(refDate) : ''} — último dia com dados${bipTime ? ` · bip ${bipTime}` : ''}`;
80	  }
81	
82	  return (
83	    <section
84	      className={`flex flex-col rounded-2xl bg-tv-surface p-5 transition-[border-color,box-shadow] [transition-duration:400ms] motion-reduce:transition-none ${frame.cls}`}
85	      style={frame.shadow ? { boxShadow: frame.shadow } : undefined}
86	      data-testid="tv-store-card"
87	      data-rag={store.rag}
88	    >
89	      {/* Header: nome + chips */}
90	      <div className="flex h-8 items-center justify-between gap-3">
91	        <h2 className="truncate text-[28px] font-momma font-semibold leading-8 text-tv-text">
92	          {store.nome}
93	        </h2>
94	        <div className="flex shrink-0 items-center gap-2">
95	          <TvStateChip rag={store.rag} />
96	          <TvStockBadge estoque={store.estoque} />
97	          <TvSourceChip
98	            channel={channel}
99	            liveLevel={liveLevel}
100	            laggedDate={vendas?.dataReferencia ?? null}
101	          />
102	        </div>
103	      </div>
104	
105	      {/* Vendas (64px) + delta */}
106	      <div className="mt-1.5 flex items-end gap-4">
107	        <span
108	          className={`font-tv-num text-[64px] font-bold leading-none tabular-nums ${vendas ? 'text-tv-text' : 'text-tv-dim'}`}
109	          data-testid="tv-store-sales"
110	        >
111	          {vendas ? formatCompactBRL(valorAnim) : '—'}
112	        </span>
113	        {store.deltaSemana != null && refDate != null && (
114	          <span className="pb-1">
115	            <TvDeltaChip
116	              delta={store.deltaSemana}
117	              weekdayLabel={WEEKDAY_ABBR[refDate.getDay()]}
118	              size="card"
119	            />
120	          </span>
121	        )}
122	      </div>
123	      <p className="mt-1 text-[20px] font-momma font-medium leading-tight text-tv-dim">
124	        {caption}
125	      </p>
126	
127	      {/* Barra de meta */}
128	      <div className="mt-2">
129	        <TvMetaBar
130	          fillPct={fullDayPct}
131	          expectedPct={fullDayPct != null ? expected : null}
132	          color={barColor}
133	          size="card"
134	        />
135	        <p className="mt-1.5 text-[22px] font-momma leading-tight">
136	          {fullDayPct != null ? (
137	            isLive ? (
138	              <>
139	                <span className="font-medium text-tv-mut">
140	                  {Math.round(fullDayPct)}% da meta
141	                </span>
142	                <span className="text-tv-dim"> · esperado {expected}%</span>
143	              </>
144	            ) : (
145	              <span className="font-medium text-tv-mut">
146	                {Math.round(fullDayPct)}% da meta de{' '}
147	                {refDate ? WEEKDAY_ABBR[refDate.getDay()] : '—'}
148	              </span>
149	            )
150	          ) : (
151	            <span className="text-tv-dim">sem meta cadastrada</span>
152	          )}
153	        </p>
154	      </div>
155	
156	      {/* Mini-stats */}
157	      <div className="mt-auto grid grid-cols-3 gap-4">
158	        <div>
159	          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
160	            CUPONS
161	          </p>
162	          <p className="mt-0.5 font-tv-num text-[32px] font-medium leading-none text-tv-text tabular-nums">
163	            {vendas?.cupons != null ? formatInt(cuponsAnim) : '—'}
164	          </p>
165	        </div>
166	        <div>
167	          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
168	            TICKET
169	          </p>
170	          <p className="mt-0.5 font-tv-num text-[32px] font-medium leading-none text-tv-text tabular-nums">
171	            {vendas?.ticketMedio != null ? formatTicketBRL(vendas.ticketMedio) : '—'}
172	          </p>
173	        </div>
174	        <div>
175	          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
176	            FLUXO
177	          </p>
178	          <p className="mt-0.5 flex items-center gap-1 font-tv-num text-[28px] font-medium leading-none text-tv-text tabular-nums">
179	            <ArrowUpRight style={{ width: 22, height: 22 }} className="text-tv-mut" aria-hidden />
180	            {store.movimentacao.entradas}
181	            <ArrowDownRight
182	              style={{ width: 22, height: 22 }}
183	              className="ml-2 text-tv-mut"
184	              aria-hidden
185	            />
186	            {store.movimentacao.saidas}
187	          </p>
188	        </div>
189	      </div>
190	    </section>
191	  );
192	}
