1	/**
2	 * @module features/tv-dashboard/ui/TvChips
3	 *
4	 * Blocos visuais compartilhados do Painel TV: chip de delta semanal,
5	 * chip de fonte (ao vivo / atrasado / defasado Linx), chip de estado RAG,
6	 * badge de estoque e barra de % meta com tick de esperado.
7	 * Tokens e medidas: design.md §1.3–§1.6, §3 e §4.
8	 */
9	
10	import {
11	  ArrowDown,
12	  ArrowUp,
13	  CalendarClock,
14	  Check,
15	  OctagonAlert,
16	  RefreshCw,
17	  TriangleAlert,
18	} from 'lucide-react';
19	import type {
20	  TvFreshnessLevel,
21	  TvRagStatus,
22	  TvSalesChannel,
23	  TvStockAlertSummary,
24	} from '../model/types';
25	import { formatLaggedDateLabel } from '../model/tvMath';
26	import { clampPct, formatDeltaPct, type TvBarColor } from './tvFormat';
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// Delta semanal (vs mesmo dia da semana passada — nunca "ontem")
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	interface TvDeltaChipProps {
33	  /** Delta % vs mesmo dia da semana anterior. */
34	  delta: number;
35	  /** Abreviação do dia comparado ("qua."). */
36	  weekdayLabel: string;
37	  /** Tamanho: hero (28px) ou card de loja (24px). */
38	  size: 'hero' | 'card';
39	}
40	
41	/**
42	 * Chip de delta semanal. Cor `tv-mut` sempre — exceto delta ≤ −15%,
43	 * que vira âmbar (design.md §3 zona 1). Positivo nunca ganha verde.
44	 */
45	export function TvDeltaChip({ delta, weekdayLabel, size }: TvDeltaChipProps) {
46	  const isAlert = delta <= -15;
47	  const colorCls = isAlert ? 'text-tv-amber' : 'text-tv-mut';
48	  const textCls = size === 'hero' ? 'text-[28px]' : 'text-[24px]';
49	  const iconPx = size === 'hero' ? 28 : 24;
50	  const Icon = delta < 0 ? ArrowDown : ArrowUp;
51	  return (
52	    <span
53	      className={`inline-flex items-center gap-1.5 rounded-full bg-tv-raised px-4 py-1.5 font-tv-num font-medium tabular-nums leading-none ${textCls} ${colorCls}`}
54	      data-testid="tv-delta-chip"
55	    >
56	      <Icon style={{ width: iconPx, height: iconPx }} aria-hidden />
57	      {formatDeltaPct(delta)} vs {weekdayLabel}
58	    </span>
59	  );
60	}
61	
62	// ─────────────────────────────────────────────────────────────────────────────
63	// Chip de fonte (freshness honesta — design.md §4 item 1)
64	// ─────────────────────────────────────────────────────────────────────────────
65	
66	interface TvSourceChipProps {
67	  channel: TvSalesChannel;
68	  /** Freshness da fonte live (ignorado para canal Linx). */
69	  liveLevel: TvFreshnessLevel;
70	  /** Dia de referência (YYYY-MM-DD) do dado defasado Linx, ou null. */
71	  laggedDate?: string | null;
72	}
73	
74	/**
75	 * Chip de fonte do card: Degust fresco → "✓ ao vivo"; Degust atrasado →
76	 * "⟳ atrasado" (âmbar); Linx → selo NEUTRO "até DD/MM" (defasagem esperada
77	 * não é alarme).
78	 */
79	export function TvSourceChip({ channel, liveLevel, laggedDate }: TvSourceChipProps) {
80	  if (channel === 'linx-lagged') {
81	    return (
82	      <span
83	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-raised px-3 text-[20px] font-momma font-medium leading-none text-tv-mut"
84	        data-testid="tv-source-chip-lagged"
85	      >
86	        <CalendarClock style={{ width: 18, height: 18 }} aria-hidden />
87	        {laggedDate ? formatLaggedDateLabel(laggedDate) : 'sem dados'}
88	      </span>
89	    );
90	  }
91	  if (liveLevel === 'fresh') {
92	    return (
93	      <span
94	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-raised px-3 text-[20px] font-momma font-medium leading-none text-tv-sageup"
95	        data-testid="tv-source-chip-live"
96	      >
97	        <Check style={{ width: 18, height: 18 }} aria-hidden />
98	        ao vivo
99	      </span>
100	    );
101	  }
102	  return (
103	    <span
104	      className="inline-flex h-6 items-center gap-1.5 rounded-full border border-tv-amber/40 bg-tv-raised px-3 text-[20px] font-momma font-medium leading-none text-tv-amber"
105	      data-testid="tv-source-chip-stale"
106	    >
107	      <RefreshCw style={{ width: 18, height: 18 }} aria-hidden />
108	      atrasado
109	    </span>
110	  );
111	}
112	
113	// ─────────────────────────────────────────────────────────────────────────────
114	// Chip de estado RAG (redundância não-cromática lível a 3m)
115	// ─────────────────────────────────────────────────────────────────────────────
116	
117	/** Chip "⚠ ATENÇÃO" / "⛔ CRÍTICO" do header do card. Nulo em estado ok. */
118	export function TvStateChip({ rag }: { rag: TvRagStatus }) {
119	  if (rag === 'ok') return null;
120	  if (rag === 'red') {
121	    return (
122	      <span
123	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-red/15 px-3 text-[20px] font-momma font-medium leading-none text-tv-redsoft"
124	        data-testid="tv-state-chip-red"
125	      >
126	        <OctagonAlert style={{ width: 18, height: 18 }} aria-hidden />
127	        CRÍTICO
128	      </span>
129	    );
130	  }
131	  return (
132	    <span
133	      className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-amber/15 px-3 text-[20px] font-momma font-medium leading-none text-tv-amber"
134	      data-testid="tv-state-chip-amber"
135	    >
136	      <TriangleAlert style={{ width: 18, height: 18 }} aria-hidden />
137	      ATENÇÃO
138	    </span>
139	  );
140	}
141	
142	// ─────────────────────────────────────────────────────────────────────────────
143	// Badge de estoque (contagem; vermelho absorve âmbar quando há ambos)
144	// ─────────────────────────────────────────────────────────────────────────────
145	
146	/**
147	 * Badge de alerta de estoque do header. Se houver zerados E abaixo do
148	 * mínimo, mostra só o vermelho com a SOMA (design.md §4 item 1).
149	 */
150	export function TvStockBadge({ estoque }: { estoque: TvStockAlertSummary }) {
151	  const total = estoque.zerados + estoque.abaixoMinimo;
152	  if (total === 0) return null;
153	  if (estoque.zerados > 0) {
154	    return (
155	      <span
156	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-red/15 px-3 text-[20px] font-tv-num font-medium leading-none text-tv-redsoft tabular-nums"
157	        data-testid="tv-stock-badge-red"
158	      >
159	        <OctagonAlert style={{ width: 18, height: 18 }} aria-hidden />
160	        {total}
161	      </span>
162	    );
163	  }
164	  return (
165	    <span
166	      className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-amber/15 px-3 text-[20px] font-tv-num font-medium leading-none text-tv-amber tabular-nums"
167	      data-testid="tv-stock-badge-amber"
168	    >
169	      <TriangleAlert style={{ width: 18, height: 18 }} aria-hidden />
170	      {total}
171	    </span>
172	  );
173	}
174	
175	// ─────────────────────────────────────────────────────────────────────────────
176	// Barra de % meta com tick de "esperado agora"
177	// ─────────────────────────────────────────────────────────────────────────────
178	
179	const BAR_FILL_CLS: Record<TvBarColor, string> = {
180	  sage: 'bg-tv-sage',
181	  amber: 'bg-tv-amber',
182	  red: 'bg-tv-red',
183	};
184	
185	interface TvMetaBarProps {
186	  /** % do dia COMPLETO da meta já atingido (preenchimento), ou null. */
187	  fillPct: number | null;
188	  /** Posição do tick de "esperado agora" (0–100), ou null para ocultar. */
189	  expectedPct: number | null;
190	  /** Cor semântica do preenchimento (estado de venda — design.md §1.6). */
191	  color: TvBarColor;
192	  /** Altura da barra: hero 20px, card 12px. */
193	  size: 'hero' | 'card';
194	}
195	
196	/**
197	 * Barra horizontal de % meta com trilho `tv-track`, preenchimento colorido
198	 * por estado de venda e tick vertical de "esperado agora" (pró-rata).
199	 * Transição de width 600ms ease-out (design.md §8.1.3).
200	 */
201	export function TvMetaBar({ fillPct, expectedPct, color, size }: TvMetaBarProps) {
202	  const heightCls = size === 'hero' ? 'h-5' : 'h-3';
203	  const tick =
204	    size === 'hero'
205	      ? { width: 3, height: 28, offset: -4 }
206	      : { width: 2, height: 20, offset: -4 };
207	  return (
208	    <div className={`relative w-full rounded-full bg-tv-track ${heightCls}`} data-testid="tv-meta-bar">
209	      {fillPct != null && (
210	        <div
211	          className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${BAR_FILL_CLS[color]}`}
212	          style={{ width: `${clampPct(fillPct)}%` }}
213	          data-testid="tv-meta-bar-fill"
214	        />
215	      )}
216	      {expectedPct != null && (
217	        <div
218	          className="absolute rounded-full bg-tv-text/60"
219	          style={{
220	            left: `calc(${clampPct(expectedPct)}% - ${tick.width / 2}px)`,
221	            top: tick.offset,
222	            width: tick.width,
223	            height: tick.height,
224	          }}
225	          data-testid="tv-meta-bar-tick"
226	        />
227	      )}
228	    </div>
229	  );
230	}
