1	/*
2	 * Animações do Painel TV (/tv) — lista FECHADA do design.md §8.1.
3	 * Importado apenas por TvDashboard.page.tsx; nada vaza para o design system.
4	 */
5	
6	@media (prefers-reduced-motion: no-preference) {
7	  /* §8.1.5 — pixel-shift anti burn-in: ciclo de 16 min (960s), passos de
8	     1-2px com interpolação de ~2s (0.2% de 960s ≈ 1,9s) em cada troca. */
9	  @keyframes tv-pixel-shift {
10	    0% {
11	      transform: translate(0, 0);
12	    }
13	    24.8% {
14	      transform: translate(0, 0);
15	    }
16	    25% {
17	      transform: translate(1px, 1px);
18	    }
19	    49.8% {
20	      transform: translate(1px, 1px);
21	    }
22	    50% {
23	      transform: translate(0, 2px);
24	    }
25	    74.8% {
26	      transform: translate(0, 2px);
27	    }
28	    75% {
29	      transform: translate(-1px, 1px);
30	    }
31	    99.8% {
32	      transform: translate(-1px, 1px);
33	    }
34	    100% {
35	      transform: translate(0, 0);
36	    }
37	  }
38	
39	  .tv-pixel-shift {
40	    animation: tv-pixel-shift 960s ease-in-out infinite;
41	  }
42	
43	  /* §8.1.2 — fade-in de exceção nova (uma única vez) */
44	  @keyframes tv-fade-in {
45	    from {
46	      opacity: 0;
47	      transform: translateY(6px);
48	    }
49	    to {
50	      opacity: 1;
51	      transform: translateY(0);
52	    }
53	  }
54	
55	  .tv-fade-in {
56	    animation: tv-fade-in 300ms ease-out both;
57	  }
58	
59	  /* §7 — conteúdo entra com fade único de 300ms após o primeiro load */
60	  @keyframes tv-content-enter {
61	    from {
62	      opacity: 0;
63	    }
64	    to {
65	      opacity: 1;
66	    }
67	  }
68	
69	  .tv-content-enter {
70	    animation: tv-content-enter 300ms ease-out both;
71	  }
72	
73	  /* §7 — loading inicial: 3 pontos que acendem em sequência (1×/600ms),
74	     único movimento permitido fora do estado carregado. */
75	  @keyframes tv-dot {
76	    0%,
77	    100% {
78	      opacity: 0.2;
79	    }
80	    33% {
81	      opacity: 1;
82	    }
83	  }
84	
85	  .tv-dot {
86	    animation: tv-dot 1800ms steps(3, jump-none) infinite;
87	  }
88	
89	  .tv-dot:nth-child(2) {
90	    animation-delay: 600ms;
91	  }
92	
93	  .tv-dot:nth-child(3) {
