80	
81	  // Valores dos inputs (string p/ digitação livre), keyed `lojaId:dia`
82	  const [values, setValues] = useState<Record<string, string>>({});
83	  const initialized = useRef(false);
84	  useEffect(() => {
85	    if (initialized.current || !metasQuery.data) return;
86	    initialized.current = true;
87	    const next: Record<string, string> = {};
88	    for (const meta of metasQuery.data) {
89	      next[cellKey(meta.loja_id, meta.dia_semana)] =
90	        meta.valor_meta > 0 ? String(meta.valor_meta) : '';
91	    }
92	    setValues(next);
93	  }, [metasQuery.data]);
94	
95	  const saveMutation = useMutation({
96	    mutationFn: async (rows: MetaRow[]) => {
97	      const { error } = await supabase
98	        .from('metas_vendas')
99	        .upsert(rows, { onConflict: 'loja_id,dia_semana' });
100	      if (error) throw error;
101	    },
102	    onSuccess: () => {
103	      toast.success('Metas salvas com sucesso');
104	      queryClient.invalidateQueries({ queryKey: ['tv-metas', 'valores'] });
105	      queryClient.invalidateQueries({ queryKey: tvDashboardKeys.metas() });
106	    },
107	    onError: (error: Error) => {
108	      toast.error('Erro ao salvar metas', {
109	        description: error.message || 'Tente novamente em instantes.',
110	      });
111	    },
112	  });
113	
114	  const rows = useMemo(() => {
115	    const out: MetaRow[] = [];
116	    for (const loja of lojasQuery.data ?? []) {
117	      for (let dia = 0; dia <= 6; dia++) {
118	        const raw = values[cellKey(loja.id, dia)];
119	        if (raw == null || raw.trim() === '') continue;
120	        const parsed = Number(raw.replace(',', '.'));
121	        if (!Number.isFinite(parsed) || parsed < 0) continue;
122	        out.push({ loja_id: loja.id, dia_semana: dia, valor_meta: parsed });
123	      }
124	    }
125	    return out;
126	  }, [lojasQuery.data, values]);
127	
128	  const isLoading = lojasQuery.isLoading || metasQuery.isLoading;
129	
130	  return (
131	    <div className="space-y-6 p-4 md:p-6" data-testid="tv-metas-page">
132	      <div className="flex flex-wrap items-center justify-between gap-3">
133	        <div className="flex items-center gap-3">
134	          <Button
135	            variant="outline"
136	            size="icon"
137	            onClick={() => navigate('/tv')}
138	            data-mia-action="voltar-painel-tv"
139	            aria-label="Voltar para o Painel TV"
140	          >
141	            <ArrowLeft className="h-4 w-4" />
142	          </Button>
143	          <div>
144	            <h1 className="flex items-center gap-2 text-2xl font-bold">
145	              <MonitorPlay className="h-6 w-6" />
146	              Metas do Painel TV
147	            </h1>
148	            <p className="text-sm text-muted-foreground">
149	              Meta diária de vendas (R$) por loja e dia da semana — usada no % pró-rata do painel.
150	            </p>
151	          </div>
152	        </div>
153	        <Button
154	          onClick={() => saveMutation.mutate(rows)}
155	          disabled={saveMutation.isPending || isLoading || rows.length === 0}
156	          data-mia-action="salvar-metas-painel-tv"
157	        >
158	          <Save className="mr-2 h-4 w-4" />
159	          {saveMutation.isPending ? 'Salvando…' : 'Salvar metas'}
160	        </Button>
161	      </div>
162	
163	      <Card>
164	        <CardHeader>
165	          <CardTitle>Grade de metas</CardTitle>
166	          <CardDescription>
167	            Deixe em branco os dias sem meta — o painel mostra "sem meta cadastrada".
168	          </CardDescription>
169	        </CardHeader>
170	        <CardContent>
171	          {isLoading ? (
172	            <p className="py-8 text-center text-sm text-muted-foreground">
173	              Carregando metas…
174	            </p>
175	          ) : (lojasQuery.data ?? []).length === 0 ? (
176	            <p className="py-8 text-center text-sm text-muted-foreground">
